SELECT COUNT(a.id)
FROM member_activity a
LEFT JOIN coupon_info ci ON a.coupon_id = ci.id
WHERE a.deleted = 0
AND type = #{reqVO.type}
and ci.id = #{reqVO.couponId}

    and a.id != #{reqVO.id}

SELECT ma.id, ma.type, ma.status AS act_status, ma.start_time, ma.end_time, ma.scope, ma.available_num, ma.coupon_id, ma.author_id, ma.limited_num, ci.coupon_name, ci.coupon_type, ci.threshold_amount, ci.discount_amount, ci.effective_type, ci.effective_days, ci.expiration_days, ci.max_issue_count, ci.issued_count, ci.used_count FROM member_activity ma INNER JOIN coupon_info ci ON ma.coupon_id = ci.id
AND ma.deleted = 0 AND ma.status = 0 AND ma.start_time <= NOW() AND ma.end_time >= NOW() AND ci.deleted = 0 AND ci.status = 0 AND ci.issued_count < ci.max_issue_count
AND ma.type = #{reqVO.type}
AND ma.author_id = #{reqVO.authorId}
AND ma.scope IN
#{item}
